import os
import sys
import base64
import threading
from datetime import datetime, timedelta
import flet as ft
from database import get_persistent_storage_dir

DEFAULT_TRIAL_DAYS = 30
DEVELOPER_MASTER_KEY = "Almoola@2026"


def LoginView(page: ft.Page, db):
    storage_dir = get_persistent_storage_dir()
    lic_file = os.path.join(storage_dir, "almolouk_lic_v2.dat")

    def _save_lic_persistent(expiry_str, last_run_str):
        enc_exp = db.encrypt_text(expiry_str)
        enc_run = db.encrypt_text(last_run_str)
        db.set_setting("app_license_expiry", enc_exp)
        db.set_setting("app_last_run_time", enc_run)
        try:
            with open(lic_file, "w", encoding="utf-8") as lf:
                lf.write(f"{enc_exp}|{enc_run}")
        except Exception:
            pass

    def _load_lic_persistent():
        raw_exp = db.get_setting("app_license_expiry")
        raw_run = db.get_setting("app_last_run_time")
        if os.path.exists(lic_file):
            try:
                parts = open(lic_file, "r", encoding="utf-8").read().strip().split("|")
                if len(parts) >= 1 and parts[0]:
                    raw_exp = parts[0]
                    raw_run = parts[1] if len(parts) > 1 else raw_run
                    db.set_setting("app_license_expiry", raw_exp)
                    if raw_run:
                        db.set_setting("app_last_run_time", raw_run)
            except Exception:
                pass
        return raw_exp, raw_run

    def check_license_status():
        now = datetime.now()
        now_str = now.strftime("%Y-%m-%d %H:%M:%S")
        raw_expiry, raw_last_run = _load_lic_persistent()

        if not raw_expiry:
            expiry_dt = now + timedelta(days=DEFAULT_TRIAL_DAYS)
            _save_lic_persistent(expiry_dt.strftime("%Y-%m-%d %H:%M:%S"), now_str)
            return True, DEFAULT_TRIAL_DAYS, f"النسخة سارية (متبقي {DEFAULT_TRIAL_DAYS} يوم)"

        try:
            expiry_str = db.decrypt_text(raw_expiry)
            expiry_dt = datetime.strptime(expiry_str, "%Y-%m-%d %H:%M:%S")
        except Exception:
            return False, 0, "خطأ في بيانات الترخيص"

        if raw_last_run:
            try:
                last_run_dt = datetime.strptime(db.decrypt_text(raw_last_run), "%Y-%m-%d %H:%M:%S")
                if now < (last_run_dt - timedelta(minutes=10)):
                    return False, 0, "تم اكتشاف تغيير في تاريخ الجهاز! يرجى ضبط الوقت."
            except Exception:
                pass

        _save_lic_persistent(expiry_str, now_str)
        remaining = expiry_dt - now
        if remaining.total_seconds() <= 0:
            return False, 0, "انتهت فترة صلاحية هذه النسخة! يرجى التجديد من قِبل المطور."

        days_left = max(1, remaining.days + (1 if remaining.seconds > 0 else 0))
        return True, days_left, f"النسخة سارية (متبقي {days_left} يوم)"

    is_valid_license, days_remaining, license_msg = check_license_status()

    def show_msg(txt, bg=ft.Colors.RED_700):
        page.open(ft.SnackBar(content=ft.Text(txt, color=ft.Colors.WHITE, weight="bold"), bgcolor=bg, duration=4000))

    # سحب بيانات الأعضاء والمخولين من السحابة في الخلفية فور فتح شاشة الدخول
    threading.Thread(target=db.pull_records_from_cloud, daemon=True).start()

    dev_key_input = ft.TextField(label="رمز المطور السري 🔐", password=True, can_reveal_password=True, text_align="left")
    extend_days_dropdown = ft.Dropdown(
        label="فترة التمديد الجديدة",
        value="90",
        options=[
            ft.dropdown.Option("15", "15 يوماً (فترة تجريبية)"),
            ft.dropdown.Option("30", "30 يوماً (شهر واحد)"),
            ft.dropdown.Option("90", "90 يوماً (3 أشهر)"),
            ft.dropdown.Option("180", "180 يوماً (6 أشهر)"),
            ft.dropdown.Option("365", "365 يوماً (سنة كاملة)"),
            ft.dropdown.Option("3650", "10 سنوات (تفعيل دائم)"),
        ],
    )
    license_status_badge = ft.Text(
        f"🛡️ {license_msg}",
        size=12,
        weight="bold",
        color=ft.Colors.GREEN_900 if is_valid_license else ft.Colors.RED_900,
    )

    def close_dialog(e=None):
        try:
            page.close(renewal_dialog)
        except Exception:
            renewal_dialog.open = False
            page.update()

    def apply_license_renewal(e):
        nonlocal is_valid_license, days_remaining, license_msg
        if (dev_key_input.value or "").strip() != DEVELOPER_MASTER_KEY:
            show_msg("رمز المطور غير صحيح! لا تملك صلاحية التجديد ❌", ft.Colors.RED_700)
            return

        added_days = int(extend_days_dropdown.value or "90")
        now = datetime.now()
        new_expiry = now + timedelta(days=added_days)
        _save_lic_persistent(new_expiry.strftime("%Y-%m-%d %H:%M:%S"), now.strftime("%Y-%m-%d %H:%M:%S"))

        is_valid_license, days_remaining, license_msg = check_license_status()
        license_status_badge.value = f"🛡️ {license_msg}"
        license_status_badge.color = ft.Colors.GREEN_900
        login_btn.disabled = False
        login_btn.content = ft.Text("تسجيل الدخول", size=16, weight=ft.FontWeight.BOLD)

        dev_key_input.value = ""
        close_dialog()
        show_msg(f"تم حفظ وتجديد ترخيص البرنامج بنجاح لمدة {added_days} يوماً! ✔️", ft.Colors.GREEN_700)
        page.update()

    renewal_dialog = ft.AlertDialog(
        modal=True,
        title=ft.Text("تجديد صلاحية وتحديث النظام 🔑", weight="bold", color=ft.Colors.AMBER),
        content=ft.Column(
            [
                ft.Text("نافذة خاصة بالمطور (Mahammd Almoola) لتمديد صلاحية النسخة وحفظها.", size=13, color=ft.Colors.GREY_300),
                dev_key_input,
                extend_days_dropdown,
            ],
            tight=True,
            spacing=12,
        ),
        actions=[
            ft.TextButton(content=ft.Text("إلغاء"), on_click=close_dialog),
            ft.Button(
                content=ft.Text("تفعيل وحفظ الصلاحية ✔️", weight="bold"),
                on_click=apply_license_renewal,
                bgcolor=ft.Colors.GREEN_700,
                color=ft.Colors.WHITE,
            ),
        ],
    )

    def open_renewal_dialog(e):
        page.open(renewal_dialog)

    def exit_application(e):
        try:
            page.window.close()
        except Exception:
            pass
        os._exit(0)

    name_input = ft.TextField(
        label="الاسم الكامل 🏃‍♂️",
        width=300,
        filled=True,
        bgcolor=ft.Colors.with_opacity(0.85, "#1E293B"),
        color=ft.Colors.WHITE,
        text_style=ft.TextStyle(weight=ft.FontWeight.BOLD, size=15),
        border_color=ft.Colors.AMBER_700,
        border_radius=12,
        label_style=ft.TextStyle(color=ft.Colors.WHITE, weight=ft.FontWeight.BOLD),
    )

    phone_input = ft.TextField(
        label="رقم الهاتف أو الفيس بوك 📞",
        width=300,
        filled=True,
        bgcolor=ft.Colors.with_opacity(0.85, "#1E293B"),
        color=ft.Colors.WHITE,
        text_style=ft.TextStyle(weight=ft.FontWeight.BOLD, size=15),
        border_color=ft.Colors.AMBER_700,
        border_radius=12,
        label_style=ft.TextStyle(color=ft.Colors.WHITE, weight=ft.FontWeight.BOLD),
    )

    label_style = ft.TextStyle(color=ft.Colors.WHITE, weight=ft.FontWeight.BOLD, size=16)
    role_radio = ft.RadioGroup(
        content=ft.Row(
            [
                ft.Radio(value="member", label="عضو", label_style=label_style, fill_color=ft.Colors.RED_900),
                ft.Radio(value="admin", label="مخول", label_style=label_style, fill_color=ft.Colors.RED_900),
            ],
            alignment=ft.MainAxisAlignment.CENTER,
        ),
        value="member",
    )

    error_banner = ft.Text("", size=13, weight="bold", color=ft.Colors.RED_300, visible=False)

    def _norm(s):
        return " ".join(str(s or "").strip().split())

    def _find_in_table(table_name, name_val, phone_val):
        cur = db.conn.cursor()
        cur.execute(f"SELECT name, phone, facebook FROM {table_name}")
        n_target = _norm(name_val)
        p_target = _norm(phone_val)
        for r_name, r_phone, r_fb in cur.fetchall():
            if _norm(r_name) == n_target and p_target in (_norm(r_phone), _norm(r_fb)) and p_target != "":
                return _norm(r_name)
        return None

    def do_login(e):
        error_banner.visible = False
        valid_now, _, current_msg = check_license_status()
        if not valid_now:
            error_banner.value = f"⛔ {current_msg}"
            error_banner.visible = True
            show_msg(f"⛔ {current_msg}", ft.Colors.RED_800)
            page.update()
            return

        entered_name = _norm(name_input.value)
        entered_phone = _norm(phone_input.value)

        if not entered_name or not entered_phone:
            error_banner.value = "⚠️ يرجى إدخال الاسم الكامل ورقم الهاتف!"
            error_banner.visible = True
            show_msg("يرجى إدخال الاسم الكامل ورقم الهاتف! ⚠️", ft.Colors.RED_700)
            page.update()
            return

        if entered_name in ("مدير", "admin") and entered_phone in ("123", "1234"):
            page.session.set("user", entered_name)
            page.session.set("role", "admin")
            page.go("/dashboard")
            return

        found_admin = _find_in_table("admins", entered_name, entered_phone)
        found_member = _find_in_table("members", entered_name, entered_phone)

        if not found_admin and not found_member:
            show_msg("جاري التحقق من بياناتك عبر السحابة... ☁️", ft.Colors.BLUE_700)
            db.pull_records_from_cloud()
            found_admin = _find_in_table("admins", entered_name, entered_phone)
            found_member = _find_in_table("members", entered_name, entered_phone)

        if found_admin:
            page.session.set("user", found_admin)
            page.session.set("role", "admin")
            page.go("/dashboard")
            return

        if found_member:
            page.session.set("user", found_member)
            page.session.set("role", "member")
            page.go("/dashboard")
            return

        error_banner.value = "❌ البيانات غير صحيحة أو غير مسجلة في قاعدة بيانات الفريق!"
        error_banner.visible = True
        show_msg("بيانات الدخول غير صحيحة! تأكد من الاسم ورقم الهاتف المسجل ❌", ft.Colors.RED_700)
        page.update()

    login_btn = ft.Button(
        content=ft.Text("تسجيل الدخول" if is_valid_license else "النسخة منتهية الصلاحية 🔒", size=16, weight=ft.FontWeight.BOLD),
        on_click=do_login,
        disabled=not is_valid_license,
        width=185,
        height=45,
        style=ft.ButtonStyle(
            bgcolor=ft.Colors.with_opacity(0.9, "#1E293B") if is_valid_license else ft.Colors.GREY_700,
            color=ft.Colors.WHITE,
            side=ft.BorderSide(2, ft.Colors.AMBER_700 if is_valid_license else ft.Colors.GREY_500),
            shape=ft.RoundedRectangleBorder(radius=12),
        ),
    )

    exit_btn = ft.Button(
        content=ft.Text("خروج 🚪", size=15, weight=ft.FontWeight.BOLD),
        on_click=exit_application,
        width=105,
        height=45,
        style=ft.ButtonStyle(
            bgcolor=ft.Colors.RED_900,
            color=ft.Colors.WHITE,
            side=ft.BorderSide(1, ft.Colors.RED_400),
            shape=ft.RoundedRectangleBorder(radius=12),
        ),
    )

    license_bar = ft.Container(
        content=ft.Column(
            [
                ft.Row(
                    [
                        license_status_badge,
                        ft.IconButton(
                            icon=ft.Icons.VPN_KEY,
                            icon_color=ft.Colors.BLUE_900,
                            icon_size=18,
                            tooltip="تجديد الصلاحية (خاص بالمطور)",
                            on_click=open_renewal_dialog,
                        ),
                    ],
                    alignment=ft.MainAxisAlignment.SPACE_BETWEEN,
                ),
                ft.Text(
                    "حقوق النشر والتطوير محفوظة © Mahammd Almoola 2026",
                    size=10,
                    color=ft.Colors.BLUE_GREY_900,
                    weight="bold",
                ),
            ],
            spacing=2,
            horizontal_alignment=ft.CrossAxisAlignment.CENTER,
        ),
        bgcolor=ft.Colors.with_opacity(0.75, ft.Colors.YELLOW_500),
        border_radius=12,
        padding=ft.Padding.symmetric(horizontal=12, vertical=6),
        width=310,
    )

    top_title_section = ft.Container(
        content=ft.Column(
            [
                ft.Text("🏆 فريق الملوك لكرة القدم 2003 🏆", size=22, weight="bold", color=ft.Colors.AMBER),
                ft.Text("تسجيل الدخول للنظام", size=18, color=ft.Colors.WHITE, weight="bold"),
            ],
            horizontal_alignment=ft.CrossAxisAlignment.CENTER,
            spacing=4,
        ),
        margin=ft.Margin.only(top=20, bottom=85),
    )

    container_kwargs = {
        "content": ft.Column(
            [
                top_title_section,
                name_input,
                phone_input,
                ft.Container(
                    content=role_radio,
                    bgcolor=ft.Colors.with_opacity(0.75, "#0B1120"),
                    border_radius=12,
                    padding=4,
                    width=300,
                ),
                error_banner,
                ft.Row([login_btn, exit_btn], alignment=ft.MainAxisAlignment.CENTER, spacing=10),
                ft.Container(expand=True),
                license_bar,
            ],
            alignment=ft.MainAxisAlignment.START,
            horizontal_alignment=ft.CrossAxisAlignment.CENTER,
            spacing=10,
        ),
        "alignment": ft.Alignment.TOP_CENTER,
        "padding": ft.Padding.only(bottom=12),
        "bgcolor": "#0B1120",
        "expand": True,
    }

    container_kwargs["image"] = ft.DecorationImage(
        src="",
        fit=ft.BoxFit.COVER,
    )

    return ft.Container(**container_kwargs)
